#include <iostream>

int globale_zahl = 100;          // globaler Speicher

void zeige(const char* name, const void* adresse) {
    std::cout << name << " liegt bei " << adresse << std::endl;
}

int main() {
    int lokal = 5;               // Stack
    int* heap = new int(7);      // Heap

    zeige("global", static_cast<const void*>(&globale_zahl));
    zeige("stack ", static_cast<const void*>(&lokal));
    zeige("heap  ", static_cast<const void*>(heap));

    std::cout << "Groesse int: " << sizeof(int) << " Byte" << std::endl;
    std::cout << "Werte: " << globale_zahl << " " << lokal << " " << *heap << std::endl;

    delete heap;                 // Heap selbst freigeben
    return 0;
}

