#include <iostream>
#include <memory>

std::unique_ptr<int[]> zahlen_erzeugen(int anzahl) {
    auto feld = std::make_unique<int[]>(anzahl);
    for (int i = 0; i < anzahl; ++i) {
        feld[i] = (i + 1) * 10;
    }
    return feld;                  // Eigentum wandert zum Aufrufer
}

void stack_versuch() {
    int lokal = 99;
    std::cout << "lokal in der Funktion: " << lokal << std::endl;
}                                 // lokal ist hier zu Ende

int main() {
    auto feld = zahlen_erzeugen(3);
    std::cout << "nach der Funktion: " << feld[0] << " " << feld[2] << std::endl;

    stack_versuch();

    int* roh = new int(5);        // ohne unique_ptr: selbst aufraeumen
    std::cout << "roh: " << *roh << std::endl;
    delete roh;
    return 0;
}

