#include <iostream>

int main() {
    int x = 23;
    int* p = &x;                  // p speichert die Adresse von x
    int** pp = &p;                // Zeiger auf einen Zeiger

    std::cout << "Wert: " << x << std::endl;
    std::cout << "ueber p: " << *p << std::endl;
    std::cout << "ueber pp: " << **pp << std::endl;
    std::cout << "gleiche Adresse: " << (p == &x ? "ja" : "nein") << std::endl;

    *p = 42;                      // aendert x selbst
    std::cout << "x ist " << x << std::endl;

    const int* lesen = &x;        // Wert nicht aenderbar
    int* const fest = &x;         // Adresse nicht aenderbar
    *fest = 7;                    // erlaubt: Wert aendern
    std::cout << "lesen " << *lesen << " fest " << *fest << std::endl;

    int* leer = nullptr;          // zeigt auf nichts
    if (leer == nullptr) {
        std::cout << "leer zeigt nirgendwohin" << std::endl;
    }
    std::cout << "Groesse eines Zeigers: " << sizeof(p) << " Byte" << std::endl;
    return 0;
}

#include <iostream>

int main() {
    int feld[4] = {10, 20, 30, 40};
    int* p = feld;                // Feldname ist die Adresse des ersten Elements

    std::cout << "erster Wert: " << *p << std::endl;
    std::cout << "p plus 1 zeigt auf: " << *(p + 1) << std::endl;
    std::cout << "Abstand in Byte: "
              << (reinterpret_cast<const char*>(p + 1) - reinterpret_cast<const char*>(p))
              << std::endl;
    std::cout << "Abstand in Elementen: " << (p + 3 - p) << std::endl;

    int summe = 0;
    for (int* lauf = feld; lauf != feld + 4; ++lauf) {
        summe += *lauf;
    }
    std::cout << "Summe: " << summe << std::endl;
    return 0;
}

