#include <iostream>

class Zahlen {
public:
    explicit Zahlen(int anzahl) : anzahl_(anzahl), werte_(new int[anzahl]) {
        for (int i = 0; i < anzahl_; ++i) {
            werte_[i] = i * i;
        }
    }
    ~Zahlen() {                  // raeumt auf, wenn das Objekt verschwindet
        delete[] werte_;
    }
    Zahlen(const Zahlen&) = delete;             // kein Kopieren erlaubt
    Zahlen& operator=(const Zahlen&) = delete;

    int summe() const {
        int s = 0;
        for (int i = 0; i < anzahl_; ++i) {
            s += werte_[i];
        }
        return s;
    }

private:
    int anzahl_;
    int* werte_;
};

int main() {
    Zahlen zahlen(4);
    std::cout << "Summe: " << zahlen.summe() << std::endl;
    std::cout << "Kein Leck: der Destruktor ruft delete auf" << std::endl;
    return 0;
}

